            const parsed = (process.env.OSBORN_DISPLAY_SIZE || '').split('x').map(Number)
            const [dw, dh] = parsed.length === 2 && parsed.every((n) => n > 0) ? parsed : [1280, 800]
            const border = FULL_WINDOW ? (win.ow - win.iw) / 2 : 0
